let language = 'en';
const rendered = new Map();
export function t(key, ...args) {
  const template = catalogs[language][key];
  if (template === undefined) throw new Error(`Unknown translation key: ${key}`);
  const result = template.replace(/\{(\d+)\}/g, (_, index) => String(args[index] ?? ''));
  rendered.set(result, { key, args });
  return result;
}
export function initialLanguage() {
  const explicit = new URL(location.href).searchParams.get('lang');
  if (Object.hasOwn(catalogs, explicit)) return explicit;
  return (navigator.languages || [navigator.language]).map(value => value.split('-')[0]).find(value => Object.hasOwn(catalogs, value)) || 'en';
}
export function applyLanguage(next, { updateURL = true } = {}) {
  if (!Object.hasOwn(catalogs, next)) return;
  language = next;
  // Refresh existing messages without re-running analysis or modifying frame state.
  const changes = [];
  // Only application messages are translated. User filenames are never scanned.
  document.querySelectorAll('#progress-text, #toast, #duplicate-summary, #duplicate-list button, #source-empty').forEach(node => {
    const message = rendered.get(node.textContent);
    if (message) changes.push([node, message]);
  });
  for (const [node, { key, args }] of changes) node.textContent = t(key, ...args);
  document.querySelectorAll('[aria-label], [title]').forEach(node => {
    for (const attribute of ['aria-label', 'title']) {
      const message = rendered.get(node.getAttribute(attribute));
      if (message) node.setAttribute(attribute, t(message.key, ...message.args));
    }
  });
  document.querySelectorAll('[data-i18n]').forEach(node => { node.textContent = t(node.dataset.i18n); });
  for (const attribute of ['aria-label', 'title', 'content']) {
    document.querySelectorAll(`[data-i18n-${attribute}]`).forEach(node => node.setAttribute(attribute, t(node.getAttribute(`data-i18n-${attribute}`))));
  }
  document.documentElement.lang = next;
  document.getElementById('language-select').value = next;
  if (updateURL && location.protocol !== 'file:') {
    const url = new URL(location.href); url.searchParams.set('lang', next);
    history.replaceState(null, '', url);
  }
}
